-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["6732b323cbf507c2"] = { "Questi antichi pezzi di terracotta sono stati recuperati negli scavi di Uldaman. Anche se recano ben poche rune o geroglifici significativi, offrono uno sguardo eloquente sull'artigianato e sugli oggetti d'uso quotidiano dell'antica razza dei nani.", "." },
  ["6772807bd926cbfe"] = { "Per vincolare un maldestriero devi fare queste tre cose:\n\nCreare un Circle of Greater Summoning.\n\nNel Circle, aprire un portale verso Xoroth e trascinarvi fuori il maldestriero.\n\nSconfiggere il maldestriero, poi dominarne lo spirito.\n\nLe pagine seguenti spiegano nel dettaglio come compiere ciascuno di questi passi. Non sarà facile, ma hai dimostrato grandi capacità. Con concentrazione e abilità, sono certo che il maldestriero sarà tuo.\n\nContinua a leggere,\n-⟦Mor'zul Bloodbringer=Mor'zul Nerosangue⟧", "." },
  ["6786e5b103df305d"] = { "--Giorno 4--\n\nCatturato!\n\nDevo... scrivere... in fretta.\n\nAttaccato da uomini cinghiale della tribù Lamaspina. Credevo mi stessero portando ai grandi resti del dio cinghiale caduto. Invece hanno aggirato i grandi fossili e si sono diretti dritti a ovest del teschio gigante, attraverso la ⟦Gold Road=Strada dell'Oro⟧.", "." },
  ["6787e03532a0af2f"] = { "Purtroppo l'ammiraglio Proudmoore morì in battaglia prima che Jaina potesse riconciliarsi con lui o dimostrargli che gli orchi non erano più mostri assetati di sangue. Per la sua lealtà, gli orchi permisero alle forze di Jaina di tornare sane e salve a Theramore.", "." },
  ["678fd618ae9a2d2c"] = { "Non spetta alla moglie dell'umile soldato porre simili domande.\n\nEppure ora ti scrivo come vedova dell'umile soldato. Per te mio marito sarà stato un soldato fra le migliaia nei ranghi. Per me era il grande Sully Balloo, padre dei miei figli e mio unico compagno in questa vita.\n\nPerdonami se le mie domande, o grande condottiero, suonano inopportune. Ma i morti non possono porre queste domande da sé....\n\nLa tua leale suddita,\nSara Balloo", "." },
  ["67965b64f7d182de"] = { "BRACIERE DELL'INVOCAZIONE: MANUALE D'USO\n\nDove trovare i luoghi infestati\n\nINTRODUZIONE\n\nIn queste pagine sono indicati i luoghi in cui si trovano gli spiriti e le anime, caduti e corrotti, coinvolti nell'incidente dell'⟦Lord Valthalak's Amulet=Amuleto di Sire Valthalak⟧. Benché tu abbia già salvato questi miei ex compagni, è mia convinzione che echi ripugnanti del male che un tempo ne distorse gli spiriti indugino ancora in quei luoghi infestati. Tale era il potere malevolo dello spirito di lord Valthalak.\n\nInoltre, il braciere può servire a evocare lord Valthalak in persona, anche se, come in passato, nel farlo occorre la massima cautela.", "." },
  ["67a261b8b7a256b9"] = { "Il vulcano, noto come ⟦Blackrock Mountain=Massiccio Roccianera⟧, confinava a nord con la ⟦Searing Gorge=Gorgia Rovente⟧ e a sud con le ⟦Burning Steppes=Steppe Ardenti⟧. Benché Thaurissan fosse stato ucciso dalle forze che aveva scatenato, i suoi fratelli sopravvissuti furono infine resi schiavi da Ragnaros e dai suoi elementali. Ancora oggi restano nelle profondità di ⟦Blackrock=Roccianera⟧.", "." },
  ["67d5b8683b14f1a2"] = { "A nome della Masseria Buongusto, grazie ancora per occuparti di questa faccenda. Non sappiamo quale dei due gruppi abbia Metzen, ma indagare su uno qualsiasi dei due sarebbe un buon punto di partenza!\n\nIl tempo è denaro, amico, e in questo caso ne abbiamo davvero pochissimo. Agisci in fretta per salvarlo, perché questi gruppi non vanno presi alla leggera, viste le cose di cui sono capaci.\n\nComunque, le due pagine seguenti sono le richieste di riscatto che abbiamo ricevuto. Buona fortuna...", "." },
})
